class Employee {
  + name : string
}

class HeadCoach extends Employee {}

class ClubDirector extends Employee {}

class Scout extends Employee {}

class HeadScout extends Scout {}

class PlayerProfile {
  + targetPosition : string
}

class PlayerAttribute {
  + name : string
  + value : string
}

class Player {
  + name : string
}

class LongList {
  + name : string
}

class ScoutingAssignment {
  + status : string
}

class ScoutingReport {
  + pros : string
  + cons : string
  + recommendation : string
}

class ShortList {}

class Offer {}

PlayerProfile "1" -- "*" PlayerAttribute : includes
PlayerProfile "1" -- "*" Player : identifies
LongList "1" -- "*" Player : contains
ScoutingAssignment "1" -- "1" Player : investigates
ScoutingAssignment "1" -- "1" Scout : assigned to
ScoutingAssignment "1" -- "0..1" ScoutingReport : results in
ScoutingAssignment "1" -- "0..1" ScoutingAssignment : part of
Player "1" -- "0..1" ShortList : moved to
Player "1" -- "0..1" Offer : receives
ClubDirector "1" -- "*" Offer : makes

@enduml

